mapper.select:
select bp.name, bp.mobile, bpm.card_number cardNumber, bo.abbreviation, bpm.card_opening_date cardOpeningDate, sum(bpm.principal_amount + bpm.bonus_amount) principalAmount, bpm.bonus_amount bonusAmount from base_patient bp join base_patient_member bpm on bp.patient_id = bpm.patient_id join base_organization bo on bo.org_id = bp.org_id
bpm.type = #{form.type}
AND bpm.member_level_id = #{form.memberLevelId}
AND bp.org_id in
#{orgId}
AND bp.patient_id in
#{ids}
and DATE_FORMAT(bpm.card_opening_date, "%Y-%m-%d") >= DATE_FORMAT(#{form.startDate}, "%Y-%m-%d") and DATE_FORMAT(bpm.card_opening_date, "%Y-%m-%d") <= DATE_FORMAT(#{form.endDate}, "%Y-%m-%d")
group by bpm.card_opening_date desc
